public sealed interface PaymentStatus permits Pending, Completed, Failed {}

public record Pending(String transactionId) implements PaymentStatus {}
public record Completed(String transactionId, Instant timestamp) implements PaymentStatus {}
public record Failed(String reason) implements PaymentStatus {}

// Exhaustive pattern matching in action
public String process(PaymentStatus status) {
    return switch (status) {
        case Pending p -> "Waiting for " + p.transactionId();
        case Completed c -> "Finished at " + c.timestamp();
        case Failed f -> "Error: " + f.reason();
    };
}
